import org.jsoup.select.NodeVisitor;
import java.util.List;

public class CleaningVisitorTest{
private CleaningVisitor cleaningVisitor;
    private Element root;
    private Element destination;
    private Whitelist whitelist;

    @Before
    public void before(){
        whitelist = Whitelist.none();
        root = new Element(Tag.valueOf("root"), "");
        destination = new Element(Tag.valueOf("destination"), "");
        cleaningVisitor = new CleaningVisitor(root, destination);
    }

    @Test
    public void testTail_ElementSafeTag() {
        whitelist.addTags("safe");
        Node source = new Element(Tag.valueOf("safe"), "");
        cleaningVisitor.tail(source, 0);
        assertThat(cleaningVisitor.destination, is(destination.parent()));
    }

    @Test
    public void testTail_ElementUnsafeTag() {
        whitelist.addTags("unsafe");
        Node source = new Element(Tag.valueOf("unsafe"), "");
        cleaningVisitor.tail(source, 0);
        assertThat(cleaningVisitor.destination, is(destination));
    }

    @Test
    public void testTail_NonElement() {
        Node source = new TextNode("text");
        cleaningVisitor.tail(source, 0);
        assertThat(cleaningVisitor.destination, is(destination));
    }

    @Test
    public void testTail_NullSource() {
        try {
