import org.junit.Test;
import org.junit.Assert;
import org.junit.Before;
import org.junit.After; 
import org.junit.Assert.*;
import org.junit.Ignore;
import org.junit.BeforeClass;
import org.junit.AfterClass;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import org.junit.Rule;
import org.junit.rules.ExpectedException;
import org.mockito.Mockito.*
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.*;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;

public class TokenQueueTest{
@Rule
    public ExpectedException thrown= ExpectedException.none();
    private TokenQueue tokenQueue;

    @Before
    public void setUp(){
        tokenQueue = new TokenQueue("");
    }

    @After
    public void tearDown(){
        tokenQueue = null;
    }

    @Test
    public void testChompBalancedOpenBrace(){
        tokenQueue = new TokenQueue("{}");
        Assert.assertEquals("", tokenQueue.chompBalanced('{', '}'));
    }

    @Test
    public void testChompBalancedOpenParens(){
        tokenQueue = new TokenQueue("()");
        Assert.assertEquals("", tokenQueue.chompBalanced('(', ')'));
    }

    @Test
    public void testChompBalancedOpenBracket(){
        tokenQueue = new TokenQueue("[]");
        Assert.assertEquals("", tokenQueue.chompBalanced('[', ']'));
    }

    @Test
    public void testChompBalancedQuote(){
        tokenQueue = new TokenQueue("\"\"");
        Assert.assertEquals("\"", tokenQueue.chompBalanced('"', '"'));
    }

    @Test
    public void testChompBalancedQuoteSingle(){
        tokenQueue = new TokenQueue("''");
        Assert.assertEquals("'", tokenQueue.chompBalanced('\'', '\''));
    }

    @Test
    public void testChompBalancedNotFound(){
        tokenQueue = new TokenQueue("{");
        try {
            tokenQueue.chompBalanced('{', '}');
            Assert.fail("Expected Validate.fail");
        } catch (Exception e) {
            Assert.assertEquals("Did not find balanced maker at ", Validate.getErrorMessage());
        }
    }

    @Test
    public void testChompBalancedDepth(){
        tokenQueue = new TokenQueue("{{}}");
        Assert.assertEquals("{}", tokenQueue.chompBalanced('{', '}'));
    }

    @Test
    public void testChompBalancedQuoteInQuote(){
        tokenQueue = new TokenQueue("\"\\\"\"");
        Assert.assertEquals("\"\\\"\"", tokenQueue.chompBalanced('"', '"'));
    }

    @Test
    public void testChompBalancedQuoteSingleInQuote(){
        tokenQueue = new TokenQueue("\'\\\'\'");
        Assert.assertEquals("\'\\\'\'", tokenQueue.chompBalanced('\'', '\''));
    }

    @Test
    public void testChompBalancedEmpty(){
        tokenQueue = new TokenQueue("");
        Assert.assertEquals("", tokenQueue.chompBalanced('{', '}'));
    }

    @Test
    public void testChompBalancedEscapedQuote(){
        tokenQueue = new TokenQueue("\\\"");
        Assert.assertEquals("", tokenQueue.chompBalanced('"', '"'));
    }

    @Test
    public void testChompBalancedEscapedSingleQuote(){
        tokenQueue = new TokenQueue("\\\'");
        Assert.assertEquals("", tokenQueue.chompBalanced('\'', '\''));
    }
}
